6	import (
7		"errors"
8		"io"
9		"strings"
10	
11		"golang.org/x/net/html"
12	)
13	
14	// StripTags removes all HTML/XML tags from the input string.
15	// This function must *only* be used for cosmetic purposes, not to prevent code injections like XSS.
16	func StripTags(input string) string {
17		dst := &strings.Builder{}
18		src := strings.NewReader(input)
19	
20		err := stripIter(src, func(text string) bool {
21			dst.WriteString(text)
22			return true
23		})
24		if err != nil {
25			return ""
26		}
27	
28		return strings.TrimSpace(dst.String())
29	}
30	
31	// stripIter iterates over the input [io.Reader] and calls the yield function for each [html.TextToken].
32	// Other kinds of [html.TokenType] are skipped.
33	func stripIter(src io.Reader, yield func(string) bool) error {
34		tokenizer := html.NewTokenizer(src)
35	
36		for {
37			tokenType := tokenizer.Next()
38			if tokenType == html.ErrorToken {
39				break
40			}
41			if tokenType != html.TextToken {
42				continue
43			}
44	
45			// Use Text() instead of Token() to avoid allocating a Token
46			// struct (and parsing attribute slices) for every non-text tag.
47			if !yield(string(tokenizer.Text())) {
48				break
49			}
50		}
51	
52		if err := tokenizer.Err(); !errors.Is(err, io.EOF) {
53			return err
54		}
55	
56		return nil
57	}
